\documentclass[border=5pt]{standalone}
\usepackage{pgfplots}
\pgfplotsset{compat=1.18}
\usepackage{xcolor}

% 定义粉红色系
\definecolor{myPink}{RGB}{255, 182, 193} % 浅粉红
\definecolor{myDarkPink}{RGB}{219, 112, 147} % 中粉红

\begin{document}
\begin{tikzpicture}
\begin{axis}[
    title={粉红色主题示例柱状图},
    xlabel={类别},
    ylabel={数值},
    ymin=0, ymax=120,
    symbolic x coords={A, B, C, D, E, F},
    xtick=data,
    nodes near coords, % 在柱子上方显示数值
    nodes near coords align={vertical},
    every axis plot/.append style={thick},
    major grid style={dashed, myPink!30},
    grid=major,
    ymajorgrids=true,
    enlargelimits=0.15,
    bar width=30pt,
    % 使用粉红色填充和边框
    fill=myPink,
    draw=myDarkPink,
]

% 示例数据 - 如果您有自己的数据，请替换这里的坐标
\addplot[ybar, fill=myPink, draw=myDarkPink] coordinates {
    (A, 42)
    (B, 78)
    (C, 95)
    (D, 63)
    (E, 110)
    (F, 56)
};

\end{axis}
\end{tikzpicture}
\end{document}
